() => {
  const sections = document.querySelectorAll('h2, h3, [data-testid*="section"], [data-testid*="card-headline"]');
  const warSections = [];
  sections.forEach(s => {
    const text = s.textContent || '';
    if (/war/i.test(text)) {
      warSections.push({
        tag: s.tagName,
        text: text.trim().substring(0, 200),
        testid: s.getAttribute('data-testid')
      });
    }
  });
  return warSections;
}

() => {
  // Find all section headings that contain "war"
  const headings = document.querySelectorAll('h2, h3, h4, [data-testid*="section-title"], [data-testid*="card-section"]');
  const result = [];
  headings.forEach(h => {
    const text = (h.textContent || '').trim();
    if (text && /war/i.test(text) && text.length < 100) {
      result.push({
        tag: h.tagName,
        text: text,
        testid: h.getAttribute('data-testid'),
        class: h.className
      });
    }
  });
  return result;
}

() => {
  // Find all unique section titles/categories on the page
  const results = [];
  // Look for nav links, section labels, headlines
  const selectors = [
    'h2', 'h3', 'h4', 
    '[data-testid*="card-headline"]',
    '[data-testid*="section-title"]',
    '[data-testid*="section-label"]',
    'a[href*="/news/topics/"]',
    '[data-component="topic-list"] a'
  ];
  selectors.forEach(sel => {
    document.querySelectorAll(sel).forEach(el => {
      const text = (el.textContent || '').trim();
      if (text && text.length < 80) {
        results.push({
          selector: sel,
          text: text
        });
      }
    });
  });
  // Deduplicate
  const unique = {};
  results.forEach(r => {
    if (!unique[r.text]) unique[r.text] = r.selector;
  });
  return Object.keys(unique);
}

() => {
