() => {
  const allElements = document.querySelectorAll('*');
  const warMatches = [];
  const seen = new Set();

  allElements.forEach(el => {
    // Only check direct text content (not concatenated from children)
    const directText = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => n.textContent.trim())
      .join(' ');

    if (directText && /war/i.test(directText) && directText.length < 200) {
      const key = el.tagName + '|' + directText;
      if (!seen.has(key)) {
        seen.add(key);
        warMatches.push({
          tag: el.tagName,
          text: directText,
          parent: el.parentElement ? el.parentElement.tagName : '',
          href: el.getAttribute ? (el.getAttribute('href') || '') : '',
          testid: el.getAttribute ? (el.getAttribute('data-testid') || '') : ''
        });
      }
    }
  });

  return JSON.stringify(warMatches.slice(0, 100));
}

() => {
  const allElements = document.querySelectorAll('h2, h3, a, span, p, div');
  const warMatches = [];
  const seen = new Set();

  allElements.forEach(el => {
    const directText = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => n.textContent.trim())
      .join(' ')
      .trim();

    if (directText && /war/i.test(directText) && directText.length < 200) {
      const key = directText.toLowerCase();
      if (!seen.has(key)) {
        seen.add(key);
        warMatches.push({
          tag: el.tagName,
          text: directText.substring(0, 200),
          href: el.getAttribute ? (el.getAttribute('href') || '') : ''
        });
      }
    }
  });

  return JSON.stringify(warMatches.slice(0, 100));
}

() => {
  // Look for section labels (often styled as small uppercase text)
  const allElements = document.querySelectorAll('h2, h3, h4, span, a, [class*="section"], [data-testid*="section"]');
  const sectionLabels = [];
  const seen = new Set();

  allElements.forEach(el => {
    const directText = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3)
      .map(n => n.textContent.trim())
      .join(' ')
      .trim();

    // Look for short section labels
    if (directText && directText.length > 0 && directText.length < 50 && /^[A-Z]/.test(directText)) {
      const key = directText.toLowerCase();
      if (!seen.has(key)) {
        seen.add(key);
        sectionLabels.push({
          tag: el.tagName,
          text: directText,
          testid: el.getAttribute('data-testid') || ''
        });
      }
    }
  });

  return JSON.stringify(sectionLabels.slice(0, 100));
}

() => {
  const bodyText = document.body.innerText || '';
  const warMentions = [];
  const lines = bodyText.split('\n');
  lines.forEach((line, idx) => {
    if (/war/i.test(line)) {
      warMentions.push({
        line: idx,
        text: line.trim().substring(0, 200)
      });
    }
  });
  return JSON.stringify(warMentions.slice(0, 50));
}

() => {
  // Get all text content from the page
  const allText = document.body.innerText || '';
  const warLines = allText.split('\n').filter(l => l.toLowerCase().includes('war')).slice(0, 30);
  return JSON.stringify(warLines);
}

() => {
  const allText = document.body.textContent || '';
  const warIndex = allText.toLowerCase().indexOf('war');
  if (warIndex === -1) return 'No war found';

  const contexts = [];
  let pos = 0;
  while ((pos = allText.toLowerCase().indexOf('war', pos)) !== -1 && contexts.length < 30) {
    const start = Math.max(0, pos - 50);
    const end = Math.min(allText.length, pos + 100);
    contexts.push(allText.substring(start, end).replace(/\s+/g, ' ').trim());
    pos += 3;
  }
  return JSON.stringify(contexts);
}

() => {
  const allText = document.body.textContent || '';
  const lower = allText.toLowerCase();
  const matches = [];
  let pos = 0;
  while ((pos = lower.indexOf('war', pos)) !== -1 && matches.length < 50) {
    const start = Math.max(0, pos - 60);
    const end = Math.min(allText.length, pos + 80);
    const context = allText.substring(start, end).replace(/\s+/g, ' ').trim();
    matches.push(context);
    pos += 3;
  }
  return JSON.stringify({ count: matches.length, matches: matches });
}

() => {
  const bodyText = document.body.textContent || '';
  const lower = bodyText.toLowerCase();
  const warMatches = [];
  let pos = 0;
  let count = 0;
  while ((pos = lower.indexOf('war', pos)) !== -1 && count < 100) {
    const start = Math.max(0, pos - 50);
    const end = Math.min(bodyText.length, pos + 80);
    const context = bodyText.substring(start, end).replace(/\s+/g, ' ').trim();
    warMatches.push(context);
    count++;
    pos += 3;
  }
  return JSON.stringify({totalLength: bodyText.length, count: warMatches.length, matches: warMatches});
}
